import{_ as t,o as l,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const q=JSON.parse('{"title":"富国银行（Wells Fargo & Company）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/富国银行.md","filePath":"03_companies/富国银行.md"}'),o={name:"03_companies/富国银行.md"};function i(d,a,h,n,u,s){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="富国银行-wells-fargo-company" tabindex="-1">富国银行（Wells Fargo &amp; Company） <a class="header-anchor" href="#富国银行-wells-fargo-company" aria-label="Permalink to &quot;富国银行（Wells Fargo &amp; Company）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Wells Fargo &amp; Company</td></tr><tr><td>行业</td><td>银行 / 金融服务</td></tr><tr><td>成立年份</td><td>1852年</td></tr><tr><td>总部</td><td>加利福尼亚州旧金山</td></tr><tr><td>伯克希尔持股</td><td>最高约 10%（2016年前后），后逐步减持至清仓</td></tr><tr><td>首次买入</td><td>1989-1990年</td></tr><tr><td>持仓时间</td><td>约 30 年（1989年 - 2020年代初）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>富国银行是美国最大的银行之一，核心业务包括：</p><ul><li><strong>社区银行</strong>：个人及小企业存贷款业务，全美分支网络最广</li><li><strong>批发银行</strong>：企业贷款、贸易融资、资本市场服务</li><li><strong>财富管理</strong>：资产管理、私人银行、投资顾问</li><li><strong>保险</strong>：银行保险及独立保险经纪</li></ul><p>富国银行以&quot;交叉销售&quot;（cross-selling）商业模式著称，目标是向每位客户销售多种金融产品。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="早期建仓-1989-1990年" tabindex="-1">早期建仓（1989-1990年） <a class="header-anchor" href="#早期建仓-1989-1990年" aria-label="Permalink to &quot;早期建仓（1989-1990年）&quot;">​</a></h3><p>巴菲特在 1989-1990 年开始买入富国银行，当时正值储蓄贷款协会危机（S&amp;L Crisis），银行股普遍承压：</p><ul><li>股价因市场恐慌而低估</li><li>巴菲特以有吸引力的价格买入</li><li>初期买入约当时伯克希尔股票投资组合的 10%</li><li>体现了&quot;在别人恐惧时贪婪&quot;的投资理念</li></ul><h3 id="四大金刚-之一" tabindex="-1">&quot;四大金刚&quot;之一 <a class="header-anchor" href="#四大金刚-之一" aria-label="Permalink to &quot;&quot;四大金刚&quot;之一&quot;">​</a></h3><p>富国银行与美国运通、可口可乐、吉列并称为巴菲特的&quot;四大金刚&quot;（Big Four）持仓，在相当长的时间内是伯克希尔最重要的银行股投资。</p><h3 id="深度持有-1990年代-2010年代" tabindex="-1">深度持有（1990年代-2010年代） <a class="header-anchor" href="#深度持有-1990年代-2010年代" aria-label="Permalink to &quot;深度持有（1990年代-2010年代）&quot;">​</a></h3><p>巴菲特持有富国银行超过 25 年，期间：</p><table tabindex="0"><thead><tr><th>时期</th><th>重要事件</th></tr></thead><tbody><tr><td>1990年代</td><td>持续增持，成为核心持仓</td></tr><tr><td>2008-2009</td><td>金融危机期间未大幅减持，表现稳健</td></tr><tr><td>2010年代</td><td>依然是重要持仓，但开始出现监管问题</td></tr><tr><td>2016年</td><td>富国银行爆发虚假账户丑闻，巴菲特公开批评</td></tr><tr><td>2016年后</td><td>逐步减持，直至完全清仓</td></tr></tbody></table><h3 id="虚假账户丑闻-2016年" tabindex="-1">虚假账户丑闻（2016年） <a class="header-anchor" href="#虚假账户丑闻-2016年" aria-label="Permalink to &quot;虚假账户丑闻（2016年）&quot;">​</a></h3><p>2016年，富国银行被曝光为达成交叉销售目标，秘密开立了数百万个未经授权的虚假账户。</p><p><strong>巴菲特的反应：</strong></p><ul><li>公开严厉批评这一行为</li><li>2016年股东会上表示这是&quot;企业文化出了问题&quot;</li><li>随后逐步减持伯克希尔持有的富国银行股份</li></ul><h3 id="最终清仓" tabindex="-1">最终清仓 <a class="header-anchor" href="#最终清仓" aria-label="Permalink to &quot;最终清仓&quot;">​</a></h3><p>2020年代初，伯克希尔完全清仓了富国银行股票，标志着这一长达 30 年投资关系的终结。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-美国西海岸先发优势" tabindex="-1">1. 美国西海岸先发优势 <a class="header-anchor" href="#_1-美国西海岸先发优势" aria-label="Permalink to &quot;1. 美国西海岸先发优势&quot;">​</a></h3><ul><li>起源于加州，历史悠久</li><li>在加州、内华达等州分支网络密集</li><li>占据美国最有价值的消费市场之一</li></ul><h3 id="_2-交叉销售模式" tabindex="-1">2. 交叉销售模式 <a class="header-anchor" href="#_2-交叉销售模式" aria-label="Permalink to &quot;2. 交叉销售模式&quot;">​</a></h3><ul><li>高效的客户价值挖掘</li><li>单客利润率高于同业</li><li>但过度追求目标导致丑闻</li></ul><h3 id="_3-成本控制" tabindex="-1">3. 成本控制 <a class="header-anchor" href="#_3-成本控制" aria-label="Permalink to &quot;3. 成本控制&quot;">​</a></h3><ul><li>运营效率在大型银行中表现优秀</li><li>成本收入比长期保持低位</li></ul><h2 id="投资教训" tabindex="-1">投资教训 <a class="header-anchor" href="#投资教训" aria-label="Permalink to &quot;投资教训&quot;">​</a></h2><h3 id="成功因素" tabindex="-1">成功因素 <a class="header-anchor" href="#成功因素" aria-label="Permalink to &quot;成功因素&quot;">​</a></h3><ul><li>在行业危机时买入被低估的优质资产</li><li>长期持有，享受复利增长</li><li>管理层的运营能力（早期）</li></ul><h3 id="教训" tabindex="-1">教训 <a class="header-anchor" href="#教训" aria-label="Permalink to &quot;教训&quot;">​</a></h3><ul><li>企业文化一旦腐化，竞争优势可以迅速消失</li><li>丑闻揭示了过度追求数字目标的风险</li><li>即使是长期持有的好公司，也需要持续监督</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;我们喜欢在别人恐惧时贪婪。&quot; —— 1990年买入时</p></blockquote><blockquote><p>&quot;富国银行是一家卓越的银行，有着出色的管理层。&quot; —— 1990年代</p></blockquote><blockquote><p>&quot;我不喜欢虚假账户这件事。如果你的激励措施设计错了，好人也会做坏事。&quot; —— 2016年</p></blockquote><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="./美国运通.html">美国运通</a> - 同期重要持仓</li><li><a href="./可口可乐.html">可口可乐</a> - 同期重要持仓</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',44)])])}const b=t(o,[["render",i]]);export{q as __pageData,b as default};
